; >S:HIGH-PRINT; PUT "HIGH-PRINT";;*********************************;; PRINT HIGH-SCORE TABLE + SCREEN;;*********************************;PRSCRN;; PRINT EVERYTHING EXCEPT THE; HIGH-SCORE TABLE;LDX #<BITSLDY #>BITSJSR PWINT   ;* PRINT BITS;LDX #13LDA #42;POOPS;STA $C81+40,X;DEXBPL POOPS;RTS;;------------------------------;PRHISC;; PRINT HIGH-SCORE TABLE;LDA #0STA NUMB;HISC1;LDA #0STA MENATW;LDA NUMBASL ACLCADC #5STA TY;LDA #6STA TX;LDA NUMBCLCADC #$31PHAAND #7ORA #$70STA PRCOLPLA;JSR DUBHIT ;* PRINT D/H;INC TXINC TX;LDA NUMBASL AASL AASL AASL A;TAX;LDA #5STA COUNT;WALT;TXAPHA;LDA HISTBL,X;STA WALLCMP #'0;BNE FOO2;LDA MENATWBNE FOO3;LDA #32BNE FOO1;FOO2;LDA #1STA MENATW;FOO3;LDA WALL;FOO1;JSR DUBHIT;PLATAX;INX;INC TXDEC COUNTBPL WALT;INC TX;LDA #9STA COUNT;WILT;TXAPHA;LDA HISTBL,X;JSR DUBHIT   ;* PRINT IT;PLATAX;INX;INC TXDEC COUNTBPL WILT;INC NUMBLDA NUMBCMP #5BNE HISC1;RTS; ;-----------------------------;PWINT;; PRINT THE BUFFER POINTED TO; BY THE X,Y;; TABLE FORMAT =;; X,Y,COL,BYTES,0;STX ALTER1+1STX ALTER2+1STX ALTER3+1STX ALTER4+1STY ALTER1+2STY ALTER2+2STY ALTER3+2STY ALTER4+2;; POINTER;LDX #0;ALTER1;LDA $FFFF,XCMP #$FF;BEQ NZTT    ;* END OF TABLE;STA TX      ;* TEMP XINX;ALTER2 LDA $FFFF,XSTA TY      ;* TEMP YINX;TXAPHA;LDX TXLDY TYJSR XY      ;* TO SCREEN;PLATAX;ALTER4 LDA $FFFF,XSTA PRCOL;INX;LDY #0;ALTER3;LDA $FFFF,XBEQ NZT;STA (SL),Y;LDA PRCOLSTA (CL),Y;INYINXBNE ALTER3;NZT;INXBNE ALTER1;NZTT;RTS;;-----------------------------;BITS;.BYTE 3,17,$66,3,$F,$E,$14,$12,$0F,$0C,0;; 'CONTROL';.BYTE 5,18,$76,$3C,$26,$3E,0;; '(F1)';.BYTE 5,20,$79,136,137,138,0.BYTE 5,21,$79,139,140,141,0;; K/J CHARS;.BYTE 14,17,$77,74,80,98,72,0.BYTE 14,18,$54,75,81,99,73,0;; FIRE; FIRE;.BYTE 15,19,$77,102,92,0.BYTE 15,20,$54,103,93,0;; TO; TO;.BYTE 14,21,$77,94,86,64,112,0.BYTE 14,22,$54,95,87,65,113,0;; PLAY; PLAY;.BYTE 24,17,$66,$13,$0F,$15,$0E,$04,0;; 'SOUND';.BYTE 25,18,$66,$3C,$27,$3E,0;; '(F2)';.BYTE 25,20,$71,142,143,144,0.BYTE 25,21,$71,145,146,147,0;; QUIET CHARS;;********;.BYTE 9,2,$64,70,92,98,84,100,32,32,70,80,86,72,88,88,64,0.BYTE 9,3,$44,71,93,99,85,101,32,32,71,81,87,73,89,89,65,0;; DORKS  DILEMMA;;********;.BYTE $FF;; END OF TABLE;;;-------------------------------;; PRINT 'ACC' (ASC) TO DOUBLE; HEIGHT AT X,Y AND COLOUR PRCOL;DUBHIT;AND #$3F;CMP #32BNE NTSPC;RTS;NTSPC;CMP #$30 ;* '0'BCC LETTER;AND #$0F;ASL ACLCADC #116BNE BYPASS;LETTER;ASL ACLCADC #62;BYPASS;PHA;LDX TXLDY TY;JSR XY     ;* TO SCREEN;; JASON NOW ADD THE X VALUE;PLA;LDY #0STA (SL),YPHA;LDA PRCOLSTA (CL),Y;PLA;CLCADC #1LDY #40STA (SL),Y;LDA PRCOLAND #$0FORA #$60STA (CL),Y;RTS;;;.END